import { basename, resolve } from 'node:path';
const cache = resolve('../../..');
if (basename(cache) !== 'cache') throw new Error('TPM Observatory requires an installed plugin cache');
const owner = basename(resolve('..')) + '-' + basename(resolve('../..'));
process.env.PLUGIN_DATA = resolve(cache, '../data', owner);
await import('./dist/server.js');
